#include <iostream>
#include <string>

class GradeBook {
public:
    explicit GradeBook(std::string name);
    void setCourseName(std::string name);
    std::string getCourseName() const;
    void displayMessage() const;
private:
    std::string courseName;
};

// Constructor delegates validation to setCourseName
GradeBook::GradeBook(std::string name) {
    setCourseName(name);
}

// Validates and limits course name to 25 characters
void GradeBook::setCourseName(std::string name) {
    if (name.size() <= 25) {
        courseName = name;
    }
    if (name.size() > 25) {
        courseName = name.substr(0, 25); // start index 0, length 25
        std::cout << "Name \"" << name << "\" exceeds maximum length (25).\n"
                  << "Limiting courseName to first 25 characters.\n";
    }
}

std::string GradeBook::getCourseName() const {
    return courseName;
}

void GradeBook::displayMessage() const {
    std::cout << "Welcome to the grade book for\n" << getCourseName() << "!\n";
}

int main() {
    GradeBook gradeBook1("CS101 Introduction to C++ Programming");
    GradeBook gradeBook2("CS102 Data Structures");

    std::cout << "gradeBook1: " << gradeBook1.getCourseName() << "\n"
              << "gradeBook2: " << gradeBook2.getCourseName() << std::endl;
    return 0;
}
